der":1},{"target_name":"Soirée citron","target_type":"finished","target_category":"patisserie","component_name":"Pistolet Jaune","component_order":2},{"target_name":"Soirée citron","target_type":"finished","target_category":"patisserie","component_name":"Crème citron","component_order":3},{"target_name":"Soirée noire","target_type":"finished","target_category":"patisserie","component_name":"Mousse noire","component_order":1},{"target_name":"Soirée noire","target_type":"finished","target_category":"patisserie","component_name":"Crème framboise","component_order":2},{"target_name":"Soirée noire","target_type":"finished","target_category":"patisserie","component_name":"PISTOLET ROUGE","component_order":3},{"target_name":"Soirée noire","target_type":"finished","target_category":"patisserie","component_name":"Ganache montée","component_order":4},{"target_name":"Soirée noire","target_type":"finished","target_category":"patisserie","component_name":"PATE SABLE ROUGE","component_order":5},{"target_name":"Tablette kounafa","target_type":"finished","target_category":"patisserie","component_name":"Chocolat au lait","component_order":1},{"target_name":"Tablette kounafa","target_type":"finished","target_category":"patisserie","component_name":"Konafa pistache","component_order":2},{"target_name":"Tablette kounafa","target_type":"finished","target_category":"patisserie","component_name":"Biscuit","component_order":3},{"target_name":"Tarte amande","target_type":"finished","target_category":"cake","component_name":"PATE SABLE","component_order":1},{"target_name":"Tarte amande","target_type":"finished","target_category":"cake","component_name":"Crème amande","component_order":2},{"target_name":"Tarte amande","target_type":"finished","target_category":"cake","component_name":"Amande effilée","component_order":3},{"target_name":"Tarte citron","target_type":"finished","target_category":"cake","component_name":"PATE SABLE","component_order":1},{"target_name":"Tarte citron","target_type":"finished","target_category":"cake","component_name":"Crème au beurre","component_order":2},{"target_name":"Tarte citron","target_type":"finished","target_category":"cake","component_name":"Crème pâtissière","component_order":3},{"target_name":"Tarte citron","target_type":"finished","target_category":"cake","component_name":"Crème tarte citron","component_order":4},{"target_name":"Tarte citron","target_type":"finished","target_category":"cake","component_name":"Pistache","component_order":5},{"target_name":"Tarte fruit","target_type":"finished","target_category":"cake","component_name":"PATE SABLE ROUGE","component_order":1},{"target_name":"Tarte fruit","target_type":"finished","target_category":"cake","component_name":"Crème au beurre","component_order":2},{"target_name":"Tarte fruit","target_type":"finished","target_category":"cake","component_name":"Crème pâtissière","component_order":3},{"target_name":"Tarte fruit","target_type":"finished","target_category":"cake","component_name":"Ananas conserve","component_order":4},{"target_name":"Tarte fruit","target_type":"finished","target_category":"cake","component_name":"conserve pèche","component_order":5},{"target_name":"Tarte fruit","target_type":"finished","target_category":"cake","component_name":"Pomme","component_order":6},{"target_name":"Tarte Noix","target_type":"finished","target_category":"cake","component_name":"PATE SABLE","component_order":1},{"target_name":"Tarte Noix","target_type":"finished","target_category":"cake","component_name":"Crème amande","component_order":2},{"target_name":"Tarte Noix","target_type":"finished","target_category":"cake","component_name":"Noix","component_order":3},{"target_name":"Tarte paris Brest","target_type":"finished","target_category":"cake","component_name":"PATE SABLE ROUGE","component_order":1},{"target_name":"Tarte paris Brest","target_type":"finished","target_category":"cake","component_name":"Crème au beurre","component_order":2},{"target_name":"Tarte paris Brest","target_type":"finished","target_category":"cake","component_name":"Crème pâtissière","component_order":3},{"target_name":"Tarte paris Brest","target_type":"finished","target_category":"cake","component_name":"Praline","component_order":4},{"target_name":"Tarte paris Brest","target_type":"finished","target_category":"cake","component_name":"Amande effilée","component_order":5},{"target_name":"Tarte paris Brest","target_type":"finished","target_category":"cake","component_name":"Crème caramel","component_order":6},{"target_name":"Tarte pomme","target_type":"finished","target_category":"cake","component_name":"PATE SABLE","component_order":1},{"target_name":"Tarte pomme","target_type":"finished","target_category":"cake","component_name":"Crème amande","component_order":2},{"target_name":"Tarte pomme","target_type":"finished","target_category":"cake","component_name":"Pomme","component_order":3},{"target_name":"Tarte Soleil","target_type":"finished","target_category":"cake","component_name":"Croquant","component_order":1},{"target_name":"Tarte Soleil","target_type":"finished","target_category":"cake","component_name":"Mousse tarte soleile","component_order":2},{"target_name":"Tarte Soleil","target_type":"finished","target_category":"cake","component_name":"Coulis soleil","component_order":3},{"target_name":"Tarte Soleil","target_type":"finished","target_category":"cake","component_name":"Pistolet Jaune","component_order":4},{"target_name":"Tarte Soleil","target_type":"finished","target_category":"cake","component_name":"Ecorces d’orange","component_order":5},{"target_name":"Trompe l’œil cacahuète","target_type":"finished","target_category":"patisserie","component_name":"Silicone Cacahuète","component_order":1},{"target_name":"Trompe l’œil cacahuète","target_type":"finished","target_category":"patisserie","component_name":"Pistolet caramel","component_order":2},{"target_name":"Trompe l’œil Café","target_type":"finished","target_category":"patisserie","component_name":"Silicone Café","component_order":1},{"target_name":"Trompe l’œil Café","target_type":"finished","target_category":"patisserie","component_name":"Pistolet chocolat noire","component_order":2},{"target_name":"Trompe l’œil citron","target_type":"finished","target_category":"patisserie","component_name":"Silicone Citron","component_order":1},{"target_name":"Trompe l’œil citron","target_type":"finished","target_category":"patisserie","component_name":"Pistolet Jaune","component_order":2},{"target_name":"Trompe l’œil framboise","target_type":"finished","target_category":"patisserie","component_name":"Silicone Framboise","component_order":1},{"target_name":"Trompe l’œil framboise","target_type":"finished","target_category":"patisserie","component_name":"PISTOLET ROUGE","component_order":2},{"target_name":"Trompe l’œil mangue","target_type":"finished","target_category":"patisserie","component_name":"Silicone mangue","component_order":1},{"target_name":"Trompe l’œil mangue","target_type":"finished","target_category":"patisserie","component_name":"Pistolet vert","component_order":2},{"target_name":"Trompe l’œil Pinacolada","target_type":"finished","target_category":"patisserie","component_name":"Silicone Pinacolada","component_order":1},{"target_name":"Trompe l’œil Pinacolada","target_type":"finished","target_category":"patisserie","component_name":"Pistolet chocolat noire","component_order":2},{"target_name":"Tropical","target_type":"finished","target_category":"patisserie","component_name":"Cadre Tropical","component_order":1},{"target_name":"Tropical","target_type":"finished","target_category":"patisserie","component_name":"Ganache montée","component_order":2},{"target_name":"Tropical","target_type":"finished","target_category":"patisserie","component_name":"Glaçage mangue","component_order":3}]$links$::jsonb;
  missing_components text[];
  ambiguous_names text[];
  schema_record record;
  target_id uuid;
  component_ids uuid[];
  v_diagram_nodes jsonb;
  v_diagram_edges jsonb;
  v_recipe_id uuid;
  v_schema_count integer;
  v_missing_code_count integer;
begin
  select array_agg(distinct input.component_name order by input.component_name)
  into missing_components
  from jsonb_to_recordset(v_links) as input(
    target_name text, target_type text, target_category text, component_name text, component_order integer
  )
  where not exists (
    select 1 from products
    where is_active = true
      and type in ('raw', 'semi_finished')
      and lower(trim(products.name)) = lower(trim(input.component_name))
  )
  and not exists (
    select 1
    from jsonb_to_recordset(v_products) as product_input(
      name text, product_type text, category text, official_code text, unit text
    )
    where product_input.product_type = 'semi_finished'
      and lower(trim(product_input.name)) = lower(trim(input.component_name))
  );

  if coalesce(array_length(missing_components, 1), 0) > 0 then
    raise exception 'Run 01_insert_divers_raw_materials.sql first. Missing components: %', missing_components;
  end if;

  update products
  set type = input.product_type::product_type,
      category = input.category,
      unit = input.unit,
      code = (case when input.product_type = 'finished' then 'PF-' else 'SF-' end)
        || upper(input.category) || '-'
        || case
          when nullif(regexp_replace(input.official_code, '[^A-Za-z0-9-]+', '', 'g'), '') is not null
            then 'CODE-' || regexp_replace(input.official_code, '[^A-Za-z0-9-]+', '', 'g')
          else 'AUTO-' || upper(substr(md5(input.name), 1, 8))
        end
        || '-' || upper(substr(md5(input.name), 1, 6)),
      updated_at = now()
  from jsonb_to_recordset(v_products) as input(
    name text, product_type text, category text, official_code text, unit text
  )
  where products.type = 'raw'
    and lower(trim(products.name)) = lower(trim(input.name))
    and not exists (
      select 1 from products manufactured
      where manufactured.type = input.product_type::product_type
        and manufactured.category = input.category
        and lower(trim(manufactured.name)) = lower(trim(input.name))
    );

  update products
  set unit = input.unit, is_active = true, updated_at = now()
  from jsonb_to_recordset(v_products) as input(
    name text, product_type text, category text, official_code text, unit text
  )
  where products.type = input.product_type::product_type
    and products.category = input.category
    and lower(trim(products.name)) = lower(trim(input.name));

  insert into products (code, name, type, category, unit)
  select
    (case when input.product_type = 'finished' then 'PF-' else 'SF-' end)
      || upper(input.category) || '-'
      || case
        when nullif(regexp_replace(input.official_code, '[^A-Za-z0-9-]+', '', 'g'), '') is not null
          then 'CODE-' || regexp_replace(input.official_code, '[^A-Za-z0-9-]+', '', 'g')
        else 'AUTO-' || upper(substr(md5(input.name), 1, 8))
      end
      || '-' || upper(substr(md5(input.name), 1, 6)),
    input.name,
    input.product_type::product_type,
    input.category,
    input.unit
  from jsonb_to_recordset(v_products) as input(
    name text, product_type text, category text, official_code text, unit text
  )
  where not exists (
    select 1 from products
    where products.type = input.product_type::product_type
      and products.category = input.category
      and lower(trim(products.name)) = lower(trim(input.name))
  )
  on conflict (code) do nothing;

  select array_agg(name || ' (' || matches || ' matches)' order by name)
  into ambiguous_names
  from (
    select input.name, input.product_type, input.category, count(products.id) as matches
    from jsonb_to_recordset(v_products) as input(
      name text, product_type text, category text, official_code text, unit text
    )
    left join products on products.type = input.product_type::product_type
      and products.category = input.category
      and lower(trim(products.name)) = lower(trim(input.name))
    group by input.name, input.product_type, input.category
    having count(products.id) <> 1
  ) problems;

  if coalesce(array_length(ambiguous_names, 1), 0) > 0 then
    raise exception 'Missing or ambiguous imported products: %', ambiguous_names;
  end if;

  select array_agg(target_name || ' -> ' || component_name order by target_name, component_name)
  into ambiguous_names
  from (
    select distinct input.target_name, input.target_type, input.target_category, input.component_name
    from jsonb_to_recordset(v_links) as input(
      target_name text, target_type text, target_category text, component_name text, component_order integer
    )
    where not exists (
      select 1 from products
      where products.is_active = true
        and lower(trim(products.name)) = lower(trim(input.component_name))
        and (
          products.type = 'raw'
          or (products.type = 'semi_finished' and products.category = input.target_category)
          or (
            products.type = 'semi_finished'
            and 1 = (
              select count(*) from products candidate
              where candidate.type = 'semi_finished'
                and candidate.is_active = true
                and lower(trim(candidate.name)) = lower(trim(input.component_name))
            )
          )
        )
    )
  ) problems;

  if coalesce(array_length(ambiguous_names, 1), 0) > 0 then
    raise exception 'Missing or ambiguous schema components: %', ambiguous_names;
  end if;

  for schema_record in
    select input.target_name, input.target_type, input.target_category
    from jsonb_to_recordset(v_links) as input(
      target_name text, target_type text, target_category text, component_name text, component_order integer
    )
    group by input.target_name, input.target_type, input.target_category
    order by case when input.target_type = 'semi_finished' then 0 else 1 end, input.target_name
  loop
    select id into target_id
    from products
    where type = schema_record.target_type::product_type
      and category = schema_record.target_category
      and lower(trim(name)) = lower(trim(schema_record.target_name));

    select array_agg(product_id order by component_order)
    into component_ids
    from (
      select distinct on (lower(trim(input.component_name)))
        input.component_order,
        resolved_product.id as product_id
      from jsonb_to_recordset(v_links) as input(
        target_name text, target_type text, target_category text, component_name text, component_order integer
      )
      join lateral (
        select candidate.id
        from products candidate
        where candidate.type in ('raw', 'semi_finished')
          and candidate.is_active = true
          and lower(trim(candidate.name)) = lower(trim(input.component_name))
        order by
          case
            when candidate.type = 'semi_finished' and candidate.category = schema_record.target_category then 0
            when candidate.type = 'raw' then 1
            else 2
          end,
          candidate.created_at
        limit 1
      ) resolved_product on true
      where lower(trim(input.target_name)) = lower(trim(schema_record.target_name))
        and input.target_type = schema_record.target_type
        and input.target_category = schema_record.target_category
      order by lower(trim(input.component_name)), input.component_order
    ) resolved;

    with recursive diagram_tree as (
      select
        component_id as product_id,
        target_id::text as parent_node_id,
        target_id::text || '__' || component_id::text as node_id,
        1 as depth,
        ordinality::integer as component_order,
        lpad(ordinality::text, 4, '0') as path_sort,
        array[target_id, component_id] as path
      from unnest(component_ids) with ordinality as components(component_id, ordinality)
      union all
      select
        resolved_product.id as product_id,
        diagram_tree.node_id as parent_node_id,
        diagram_tree.node_id || '__' || resolved_product.id::text as node_id,
        diagram_tree.depth + 1 as depth,
        child_input.component_order,
        diagram_tree.path_sort || '.' || lpad(child_input.component_order::text, 4, '0') as path_sort,
        diagram_tree.path || resolved_product.id
      from diagram_tree
      join products parent_product on parent_product.id = diagram_tree.product_id
        and parent_product.type = 'semi_finished'
        and parent_product.is_active = true
      join jsonb_to_recordset(v_links) as child_input(
        target_name text, target_type text, target_category text, component_name text, component_order integer
      ) on lower(trim(child_input.target_name)) = lower(trim(parent_product.name))
        and child_input.target_type = parent_product.type::text
        and child_input.target_category = parent_product.category
      join lateral (
        select candidate.id
        from products candidate
        where candidate.type in ('raw', 'semi_finished')
          and candidate.is_active = true
          and lower(trim(candidate.name)) = lower(trim(child_input.component_name))
        order by
          case
            when candidate.type = 'semi_finished' and candidate.category = parent_product.category then 0
            when candidate.type = 'raw' then 1
            else 2
          end,
          candidate.created_at
        limit 1
      ) resolved_product on not resolved_product.id = any(diagram_tree.path)
    ),
    ordered_nodes as (
      select
        product_id,
        parent_node_id,
        node_id,
        depth,
        row_number() over (order by path_sort, product_id::text) as row_index,
        count(*) over () as total_nodes
      from diagram_tree
    )
    select
      jsonb_build_array(
        jsonb_build_object(
          'id', target_id::text,
          'type', 'product',
          'position', jsonb_build_object('x', -320, 'y', 0),
          'data', jsonb_build_object('productId', target_id::text, 'isTarget', true)
        )
      ) || coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', node_id,
            'type', 'product',
            'position', jsonb_build_object(
              'x', ((depth - 1) * 320),
              'y', ((row_index - ((total_nodes::numeric + 1) / 2)) * 165)::integer
            ),
            'data', jsonb_build_object('productId', product_id::text, 'isTarget', false)
          )
          order by row_index
        ),
        '[]'::jsonb
      ),
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', parent_node_id || '->' || node_id,
            'source', parent_node_id,
            'target', node_id,
            'type', 'smoothstep'
          )
          order by row_index
        ),
        '[]'::jsonb
      )
    into v_diagram_nodes, v_diagram_edges
    from ordered_nodes;

    select id into v_recipe_id
    from recipes
    where product_id = target_id and is_active = true
    order by version desc
    limit 1;

    if v_recipe_id is null then
      insert into recipes (product_id, version, is_active, notes, diagram_nodes, diagram_edges, diagram_viewport)
      values (
        target_id,
        coalesce((select max(version) from recipes where product_id = target_id), 0) + 1,
        true,
        'Casabianca recipe document import',
        v_diagram_nodes,
        v_diagram_edges,
        jsonb_build_object('x', 0, 'y', 0, 'zoom', 0.9)
      )
      returning id into v_recipe_id;
    else
      update recipes
      set notes = 'Casabianca recipe document import',
          diagram_nodes = v_diagram_nodes,
          diagram_edges = v_diagram_edges,
          diagram_viewport = jsonb_build_object('x', 0, 'y', 0, 'zoom', 0.9)
      where id = v_recipe_id;
    end if;

    update recipes set is_active = false
    where product_id = target_id and id <> v_recipe_id and is_active = true;

    delete from recipe_components where recipe_components.recipe_id = v_recipe_id;

    insert into recipe_components (recipe_id, component_product_id, quantity, unit)
    select v_recipe_id, component_id, null, null
    from unnest(component_ids) component_id;

    update products set updated_at = now() where id = target_id;
  end loop;

  select count(*) into v_schema_count
  from (
    select distinct input.target_name, input.target_type, input.target_category
    from jsonb_to_recordset(v_links) as input(
      target_name text, target_type text, target_category text, component_name text, component_order integer
    )
  ) schemas;

  select count(*) into v_missing_code_count
  from jsonb_to_recordset(v_products) as input(
    name text, product_type text, category text, official_code text, unit text
  )
  where input.official_code is null;

  raise notice 'Imported % products, % schemas, % component links. % products have no official codification.',
    jsonb_array_length(v_products), v_schema_count, jsonb_array_length(v_links), v_missing_code_count;
end
$import$;
